var list = document.getElementById('search-result');
if (list && element.parentNode === list) {
  if (list.firstChild !== element) {
    list.insertBefore(element, list.firstChild);
  }
}

var list = document.getElementById('search-result');
if (!list || element.parentNode === list) return;

var li = document.createElement('li');
li.className = 'serp-item serp-item_card';
li.setAttribute('data-cid', element.getAttribute('data-cid') || '');
li.setAttribute('data-log-node', element.getAttribute('data-log-node') || '');
li.setAttribute('data-fast', element.getAttribute('data-fast') || '');
li.setAttribute('data-fast-name', 'images');
li.setAttribute('data-fast-subtype', element.getAttribute('data-fast-subtype') || '');

var root = element.querySelector('.Root');
if (root) {
  li.appendChild(root);
} else {
  while (element.firstChild) {
    li.appendChild(element.firstChild);
  }
}

element.parentNode.replaceChild(li, element);

var firstLi = list.querySelector('li[data-fast-name="video-unisearch"]');
if (firstLi && list.contains(firstLi)) {
  list.insertBefore(li, firstLi);
} else {
  if (list.firstChild) {
    list.insertBefore(li, list.firstChild);
  } else {
    list.appendChild(li);
  }
}
